import { queueGroupId } from '@app/web-player/queue-group-id';
import { PlayArrowFilledIcon } from '@app/web-player/tracks/play-arrow-filled';
import { Track } from '@app/web-player/tracks/track';
import { TrackImage } from '@app/web-player/tracks/track-image/track-image';
import { getTrackLink, TrackLink } from '@app/web-player/tracks/track-link';
import { tracksToMediaItems } from '@app/web-player/tracks/utils/track-to-media-item';
import { usePlayerActions } from '@common/player/hooks/use-player-actions';
import { Button } from '@ui/buttons/button';
import { FormattedDate } from '@ui/i18n/formatted-date';
import { Trans } from '@ui/i18n/trans';
import { Link } from 'react-router';

interface NewReleaseCardProps {
  track?: Track;
}

export function NewReleaseCard({track}: NewReleaseCardProps) {
  const player = usePlayerActions();

  return (
    <div className="flex h-full flex-col gap-12">
      <h2 className="text-base font-semibold">
        <Trans message="New release" />
      </h2>
      {track ? (
        <>
          {(() => {
            const queueId = queueGroupId(track);
            const releaseDate = track.album?.release_date || track.created_at;

            const handlePlay = async () => {
              const mediaItems = await tracksToMediaItems([track], queueId);
              await player.overrideQueueAndPlay(mediaItems, 0);
            };

            return (
              <div className="h-full rounded-lg bg-chip p-8 flex flex-col justify-between">
                <div>
                  <Link to={getTrackLink(track)} className="block w-full cursor-pointer hover:opacity-80 transition-opacity">
                    <TrackImage
                      track={track}
                      size="w-full aspect-square"
                      className="rounded-lg"
                    />
                  </Link>
                  <div className="w-full mt-6">
                    <div className="mb-2 text-[10px] uppercase text-muted">
                      <Trans message="VIEW TRACK" />
                    </div>
                    <TrackLink
                      track={track}
                      className="text-sm font-semibold line-clamp-1 hover:underline"
                    />
                  </div>
                </div>
                <div className="flex justify-center">
                  <Button
                    onClick={handlePlay}
                    variant="flat"
                    color="primary"
                    radius="rounded-full"
                    size="xs"
                    startIcon={<PlayArrowFilledIcon />}
                    className="text-xs"
                  >
                    <Trans message="Play now" />
                  </Button>
                </div>
                {releaseDate && (
                  <div className="text-xs text-muted text-right">
                    <FormattedDate date={releaseDate} />
                  </div>
                )}
              </div>
            );
          })()}
        </>
      ) : (
        <div className="rounded-lg bg-chip p-12 text-sm text-muted">
          <Trans message="No new releases" />
        </div>
      )}
    </div>
  );
}
